# -*- coding: utf-8 -*-
from entries1 import E, IKHLAS_FR
# ---------------- APRÈS LA PRIÈRE ----------------
G='apres_priere'
E('66','apres_priere',"Astaghfirullah (3 fois)","Je demande pardon à Allah.",c=3,v=[('muslim',591)],
  ar="أَسْتَغْفِرُ اللَّهَ",tr="Astaghfirullāh",id='z66a')
E('66','apres_priere',"« Ô Allah, Tu es la Paix… »","Ô Allah, Tu es la Paix (As-Salâm) et de Toi vient la paix. Béni sois-Tu, ô Détenteur de la majesté et de la générosité.",
  v=[('muslim',591)],ar="اللّهُـمَّ أَنْـتَ السَّلامُ، وَمِـنْكَ السَّلام، تَبارَكْتَ يا ذا الجَـلالِ وَالإِكْـرام",
  tr="Allāhumma antas-salām, wa minkas-salām, tabārakta yā dhal-Jalāli wal-'Ikrām.",id='z66b')
E('67',G,"« Nul ne peut retenir ce que Tu donnes »","Il n'y a de divinité digne d'adoration qu'Allah, Seul, sans associé. À Lui la royauté, à Lui la louange, et Il est capable de toute chose. Ô Allah, nul ne peut retenir ce que Tu donnes, nul ne peut donner ce que Tu retiens, et la fortune du fortuné ne lui sert à rien contre Toi.")
E('68',G,"« Lâ hawla wa lâ quwwata illâ billâh… wa lâ na'budu illâ iyyâh »","Il n'y a de divinité digne d'adoration qu'Allah, Seul, sans associé. À Lui la royauté, à Lui la louange, et Il est capable de toute chose. Il n'y a de force ni de puissance qu'en Allah. Il n'y a de divinité qu'Allah et nous n'adorons que Lui. À Lui le bienfait, à Lui la grâce et à Lui la belle louange. Il n'y a de divinité qu'Allah ; nous Lui vouons un culte exclusif, même si les mécréants le détestent.")
E('69',G,"Subhanallah (33 fois)","Gloire à Allah.",c=33,v=[('muslim',597),('bukhari',843)],ar="سُبْحَانَ اللَّهِ",tr="Subḥānallāh",id='z69a',
  b="Celui qui dit ces trois formules 33 fois chacune après chaque prière puis complète la centaine par le tahlil voit ses péchés pardonnés, seraient-ils comme l'écume de la mer (Muslim 597).")
E('69',G,"Alhamdulillah (33 fois)","Louange à Allah.",c=33,v=[('muslim',597)],ar="الْحَمْدُ لِلَّهِ",tr="Al-ḥamdu lillāh",id='z69b')
E('69',G,"Allahu Akbar (33 fois)","Allah est le plus Grand.",c=33,v=[('muslim',597)],ar="اللَّهُ أَكْبَرُ",tr="Allāhu akbar",id='z69c',
  note="Une autre version authentique donne 34 fois « Allahu Akbar » (sans le tahlil final).")
E('69',G,"Tahlil pour compléter la centaine","Il n'y a de divinité digne d'adoration qu'Allah, Seul, sans associé. À Lui la royauté, à Lui la louange, et Il est capable de toute chose.",
  v=[('muslim',597)],ar="لا إلهَ إلاّ اللّهُ وَحْـدَهُ لا شريكَ لهُ، لهُ الملكُ ولهُ الحَمْد، وهُوَ على كُلّ شَيءٍ قَـدير",
  tr="Lā 'ilāha 'illallāh, waḥdahu lā sharīka lahu, lahul-mulku wa lahul-ḥamd, wa huwa 'alā kulli shay'in qadīr.",id='z69d')
E('71',G,"Ayat al-Kursi après chaque prière","Allah ! Il n'y a de divinité digne d'adoration que Lui, le Vivant, Celui qui subsiste par Lui-même et soutient toute chose. Ni somnolence ni sommeil ne Le saisissent. À Lui appartient ce qui est dans les cieux et sur la terre. Qui peut intercéder auprès de Lui sans Sa permission ? Il connaît ce qui est devant eux et ce qui est derrière eux, et ils n'embrassent de Sa science que ce qu'Il veut. Son Trône s'étend sur les cieux et la terre, et leur garde ne Lui pèse point. Et Il est le Très-Haut, le Très-Grand.",
  b="Rien ne le sépare de l'entrée au Paradis, sinon la mort (authentifié par Al-Albani, As-Sahiha n°972).")
E('70',G,"Ikhlas, Falaq et Nas après la prière",IKHLAS_FR,c=1,v=[('abudawud',1523),('nasai',1336),('tirmidhi',2903)],
  note="Une fois après chaque prière ; Hisn al-Muslim recommande 3 fois après le Fajr et le Maghrib.")
E('72',G,"Tahlil 10 fois après le Fajr et le Maghrib","Il n'y a de divinité digne d'adoration qu'Allah, Seul, sans associé. À Lui la royauté, à Lui la louange ; Il donne la vie et la mort, et Il est capable de toute chose.",c=10,
  ar="لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، يُحْيِي وَيُمِيتُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ")
E('73',G,"Après le Fajr : science utile, bonne subsistance","Ô Allah, je Te demande une science utile, une subsistance pure et des œuvres agréées.",note="Après le salâm de la prière du Fajr.")
E('74',G,"Prière de consultation (Istikhara)","Ô Allah, je Te demande de me guider par Ta science, je Te demande de m'en donner la capacité par Ta puissance, et je Te demande de Ta grâce immense : Tu peux et je ne peux pas, Tu sais et je ne sais pas, et Tu es le Grand Connaisseur de l'invisible. Ô Allah, si Tu sais que cette affaire [la nommer] est un bien pour moi dans ma religion, ma vie et l'issue de mes affaires, alors décrète-la pour moi, facilite-la-moi et bénis-la pour moi. Et si Tu sais que cette affaire est un mal pour moi dans ma religion, ma vie et l'issue de mes affaires, alors écarte-la de moi, écarte-moi d'elle, décrète pour moi le bien où qu'il soit, puis rends-m'en satisfait.",
  note="Après deux unités de prière surérogatoire.")

# ---------------- COUCHER / NUIT ----------------
G='coucher'
E('99',G,"Ikhlas, Falaq, Nas dans les paumes (3 fois)",IKHLAS_FR,c=3,v=[('bukhari',5017)],ar='@76',tr='@76',
  note="Joindre les paumes, souffler dedans, réciter les trois sourates, puis passer les mains sur le corps (tête, visage, devant du corps). Le faire 3 fois.")
E('100',G,"Ayat al-Kursi avant de dormir","Allah ! Il n'y a de divinité digne d'adoration que Lui, le Vivant, Celui qui subsiste par Lui-même et soutient toute chose. Ni somnolence ni sommeil ne Le saisissent. À Lui appartient ce qui est dans les cieux et sur la terre. Qui peut intercéder auprès de Lui sans Sa permission ? Il connaît ce qui est devant eux et ce qui est derrière eux, et ils n'embrassent de Sa science que ce qu'Il veut. Son Trône s'étend sur les cieux et la terre, et leur garde ne Lui pèse point. Et Il est le Très-Haut, le Très-Grand.",
  v=[('bukhari',2311)],b="Un gardien venant d'Allah reste auprès de lui et le Diable ne l'approche pas jusqu'au matin.")
E('101',G,"Les deux derniers versets d'Al-Baqara (2:285-286)","Le Messager a cru en ce qui lui a été révélé par son Seigneur, de même que les croyants : tous ont cru en Allah, en Ses anges, en Ses livres et en Ses messagers — « Nous ne faisons aucune distinction entre Ses messagers » — et ils ont dit : « Nous avons entendu et nous avons obéi. Ton pardon, notre Seigneur ! C'est vers Toi le retour. » Allah n'impose à aucune âme une charge supérieure à sa capacité : à elle le bien qu'elle a acquis, contre elle le mal qu'elle a commis. « Notre Seigneur, ne nous châtie pas si nous oublions ou commettons une erreur. Notre Seigneur, ne nous charge pas d'un fardeau comme Tu en as chargé ceux qui nous ont précédés. Notre Seigneur, ne nous impose pas ce que nous ne pouvons supporter. Efface nos fautes, pardonne-nous et fais-nous miséricorde. Tu es notre Maître : donne-nous la victoire sur les gens mécréants. »",
  b="Ces deux versets suffisent à celui qui les récite la nuit.")
E('102',G,"« C'est en Ton nom, Seigneur, que je me couche »","C'est en Ton nom, mon Seigneur, que je pose mon flanc et c'est par Toi que je le relève. Si Tu retiens mon âme, fais-lui miséricorde ; et si Tu la renvoies, protège-la comme Tu protèges Tes serviteurs vertueux.",
  v=[('bukhari',6320),('muslim',2714)],note="Épousseter d'abord le lit trois fois avec un pan de son vêtement en mentionnant le nom d'Allah.")
E('103',G,"« Ô Allah, c'est Toi qui as créé mon âme »","Ô Allah, c'est Toi qui as créé mon âme et c'est Toi qui la reprends ; à Toi sa mort et sa vie. Si Tu la fais vivre, protège-la ; et si Tu la fais mourir, pardonne-lui. Ô Allah, je Te demande le bien-être (al-'âfiya).")
E('104',G,"« Ô Allah, préserve-moi de Ton châtiment »","Ô Allah, préserve-moi de Ton châtiment le Jour où Tu ressusciteras Tes serviteurs.",note="Le Prophète ﷺ le disait en posant sa main droite sous sa joue.")
E('105',G,"« C'est en Ton nom, ô Allah, que je meurs et que je vis »","C'est en Ton nom, ô Allah, que je meurs et que je vis.",v=[('bukhari',6324)])
E('106',G,"Avant de dormir : Subhanallah (33 fois)","Gloire à Allah.",c=33,v=[('bukhari',3113),('muslim',2727)],ar="سُبْحَانَ اللَّهِ",tr="Subḥānallāh",id='z106a',
  b="Le Prophète ﷺ l'enseigna à Fatima et Ali comme meilleur pour eux qu'un serviteur.")
E('106',G,"Avant de dormir : Alhamdulillah (33 fois)","Louange à Allah.",c=33,v=[('bukhari',3113),('muslim',2727)],ar="الْحَمْدُ لِلَّهِ",tr="Al-ḥamdu lillāh",id='z106b')
E('106',G,"Avant de dormir : Allahu Akbar (34 fois)","Allah est le plus Grand.",c=34,v=[('bukhari',3113),('muslim',2727)],ar="اللَّهُ أَكْبَرُ",tr="Allāhu akbar",id='z106c')
E('107',G,"« Ô Allah, Seigneur des sept cieux »","Ô Allah, Seigneur des sept cieux et Seigneur du Trône immense, notre Seigneur et Seigneur de toute chose, Toi qui fends le grain et le noyau, qui as révélé la Torah, l'Évangile et le Discernement (le Coran), je me réfugie auprès de Toi contre le mal de toute chose que Tu tiens par le toupet. Ô Allah, Tu es le Premier, rien n'est avant Toi ; Tu es le Dernier, rien n'est après Toi ; Tu es l'Apparent, rien n'est au-dessus de Toi ; Tu es le Caché, rien n'est en deçà de Toi. Acquitte pour nous nos dettes et préserve-nous de la pauvreté.")
E('108',G,"« Louange à Allah qui nous a nourris »","Louange à Allah qui nous a nourris, abreuvés, suffi et donné un abri. Combien sont ceux qui n'ont personne pour leur suffire ni pour les abriter !",v=[('muslim',2715)])
E('109',G,"« Ô Allah, Connaisseur de l'invisible » (au coucher)","Ô Allah, Connaisseur de l'invisible et du visible, Créateur des cieux et de la terre, Seigneur de toute chose et son Maître, je témoigne qu'il n'y a de divinité digne d'adoration que Toi. Je me réfugie auprès de Toi contre le mal de mon âme, contre le mal du Diable et de son polythéisme, et contre le fait de commettre une faute contre moi-même ou de l'entraîner vers un musulman.",
  v=[('abudawud',5067),('tirmidhi',3392)])
E('110',G,"Réciter les sourates As-Sajda et Al-Mulk","Le Prophète ﷺ ne dormait pas avant d'avoir récité la sourate As-Sajda (32) et la sourate Al-Mulk (67).",
  ar="يَقْرَأُ ﴿الم ۝ تَنْزِيلُ﴾ السَّجْدَةَ، وَ﴿تَبَارَكَ الَّذِي بِيَدِهِ الْمُلْكُ﴾",tr="Sūrat as-Sajdah (32) wa Sūrat al-Mulk (67)")
E('111',G,"« Ô Allah, je me soumets à Toi » (dernière parole avant de dormir)","Ô Allah, je Te soumets ma personne, je Te confie mon affaire, je tourne mon visage vers Toi et je m'appuie sur Toi, par désir de Toi et par crainte de Toi. Il n'y a de refuge ni de salut contre Toi qu'auprès de Toi. Je crois au Livre que Tu as révélé et au Prophète que Tu as envoyé.",
  v=[('bukhari',6311),('muslim',2710)],b="Celui qui meurt cette nuit-là meurt sur la fitra.",note="Faire les ablutions, se coucher sur le côté droit, et en faire ses dernières paroles.")
E('112',G,"En se retournant dans son lit la nuit","Il n'y a de divinité digne d'adoration qu'Allah, l'Unique, le Dominateur suprême, Seigneur des cieux, de la terre et de ce qui est entre eux, le Tout-Puissant, le Grand Pardonneur.")
E('113',G,"En cas de peur ou d'insomnie","Je me réfugie dans les paroles parfaites d'Allah contre Sa colère et Son châtiment, contre le mal de Ses serviteurs, contre les suggestions des diables et contre leur présence.")

# ---------------- RÉVEIL ----------------
G='reveil'
E('1',G,"« Louange à Allah qui nous a rendu la vie »","Louange à Allah qui nous a rendu la vie après nous avoir fait mourir, et vers Lui est la résurrection.",v=[('bukhari',6324)])
E('2',G,"En se réveillant la nuit","Il n'y a de divinité digne d'adoration qu'Allah, Seul, sans associé. À Lui la royauté, à Lui la louange, et Il est capable de toute chose. Gloire à Allah, louange à Allah, il n'y a de divinité qu'Allah, Allah est le plus Grand, et il n'y a de force ni de puissance qu'en Allah, le Très-Haut, l'Immense. Seigneur, pardonne-moi.",
  b="Celui qui le dit est pardonné ; s'il invoque, il est exaucé ; s'il fait ses ablutions et prie, sa prière est acceptée.")
E('3',G,"« Louange à Allah qui m'a rendu la santé »","Louange à Allah qui m'a donné la santé dans mon corps, m'a rendu mon âme et m'a permis de L'invoquer.")
E('4',G,"Fin de la sourate Al 'Imran (3:190-200)","Dans la création des cieux et de la terre, et dans l'alternance de la nuit et du jour, il y a certes des signes pour les doués d'intelligence, qui invoquent Allah debout, assis et couchés sur le côté, et méditent sur la création des cieux et de la terre : « Notre Seigneur, Tu n'as pas créé tout cela en vain. Gloire à Toi ! Garde-nous du châtiment du Feu. Notre Seigneur, celui que Tu fais entrer au Feu, Tu l'as couvert d'opprobre, et les injustes n'auront aucun secoureur. Notre Seigneur, nous avons entendu un appelant appeler à la foi : “Croyez en votre Seigneur”, et nous avons cru. Notre Seigneur, pardonne-nous nos péchés, efface nos mauvaises actions et fais-nous mourir avec les vertueux. Notre Seigneur, donne-nous ce que Tu nous as promis par Tes messagers et ne nous couvre pas d'opprobre au Jour de la Résurrection : Tu ne manques jamais à Ta promesse. » Leur Seigneur leur répondit : « Je ne laisse pas perdre l'œuvre d'aucun d'entre vous, homme ou femme, vous êtes issus les uns des autres. Ceux qui ont émigré, ont été chassés de leurs demeures, persécutés dans Mon chemin, qui ont combattu et ont été tués, J'effacerai leurs mauvaises actions et les ferai entrer dans des jardins sous lesquels coulent les rivières, récompense de la part d'Allah ; et c'est auprès d'Allah qu'est la plus belle récompense. » Que ne te trompe pas l'aisance des mécréants dans le pays : c'est une jouissance éphémère, puis leur refuge sera l'Enfer, et quel détestable lit ! Mais ceux qui craignent leur Seigneur auront des jardins sous lesquels coulent les rivières, pour y demeurer éternellement, en hospitalité de la part d'Allah ; et ce qui est auprès d'Allah est meilleur pour les vertueux. Il est, parmi les gens du Livre, ceux qui croient en Allah, en ce qui vous a été révélé et en ce qui leur a été révélé, humbles devant Allah, et qui ne vendent pas les versets d'Allah à vil prix : ceux-là ont leur récompense auprès de leur Seigneur. Allah est prompt à faire les comptes. Ô vous qui croyez, soyez endurants, rivalisez d'endurance, restez vigilants et craignez Allah, afin de réussir.",
  note="Le Prophète ﷺ récitait ces versets en se levant la nuit.")
